using Autodesk.Revit.DB;
var doc = Document;
// Goal: put a hipped roof over a rectangular footprint on the highest level. Reads at top level;
// the roof is created and its edge slopes set inside one WithTransaction block.

// 1. Roof base level: the highest existing level (a real task picks the roof/top storey level).
Level level = null;
foreach (Level l in new FilteredElementCollector(doc).OfClass(typeof(Level)))
  if (level == null || l.Elevation > level.Elevation) level = l;
if (level == null) throw new System.Exception("no level in document");

// 2. Roof type by name, template-dependent, so fall back to the first RoofType. Every RoofType
//    (including "Sloped Glazing") comes back from OfClass(typeof(RoofType)).
string wantedType = "Wood Rafter 8\" - Asphalt Shingle";
RoofType roofType = null, firstRt = null;
foreach (RoofType rt in new FilteredElementCollector(doc).OfClass(typeof(RoofType))) {
  if (firstRt == null) firstRt = rt;
  if (rt.Name == wantedType) { roofType = rt; break; }
}
bool usedFallback = roofType == null;
if (roofType == null) roofType = firstRt;
if (roofType == null) throw new System.Exception("no RoofType in this document");

return Connector.WithTransaction(doc, () => {
  double z = level.Elevation;
  // 3. The footprint as a CurveArray (NOT a CurveLoop): NewFootPrintRoof takes CurveArray.
  //    Expand the rectangle outward for an eave overhang if you want one.
  var pts = new[] {
    new XYZ(-1.5, -1.5, z), new XYZ(41.5, -1.5, z),
    new XYZ(41.5, 31.5, z), new XYZ(-1.5, 31.5, z)
  };
  var fp = new CurveArray();
  for (int i = 0; i < 4; i++) fp.Append(Line.CreateBound(pts[i], pts[(i + 1) % 4]));

  // 4. Create the roof. The last parameter is an OUT ModelCurveArray: Revit fills it with one
  //    ModelCurve per footprint curve, in the same order. You set slope on THESE model curves,
  //    not on the input Line objects.
  ModelCurveArray mapping = new ModelCurveArray();
  var roof = doc.Create.NewFootPrintRoof(fp, level, roofType, out mapping);

  // 5. Give every edge a slope -> a hip roof. DefinesSlope and SlopeAngle are named INDEXED
  //    PROPERTIES keyed by ModelCurve; describe_function shows them as the accessor pair
  //    "void set_DefinesSlope(ModelCurve, bool)" / "void set_SlopeAngle(ModelCurve, double)".
  //    C# has no obj[key] syntax for a named indexed property, so call the accessor exactly as
  //    shown. SlopeAngle is rise-over-run despite the name: 0.5 == 6:12 pitch. Slope a subset of
  //    edges instead for a gable (two opposite edges) or a shed/mono-pitch (one edge).
  int sloped = 0;
  foreach (ModelCurve mc in mapping) {
    roof.set_DefinesSlope(mc, true);
    roof.set_SlopeAngle(mc, 0.5);
    sloped++;
  }
  // 6. Regenerate before reading geometry back; the ridge height is not resolved until then.
  doc.Regenerate();

  var bb = roof.get_BoundingBox(null);
  double ridgeZ = bb != null ? bb.Max.Z : -1;
  return new {
    roofId = roof.Id.Value, roofType = roofType.Name, usedFallbackType = usedFallback,
    level = level.Name, slopedEdges = sloped, ridgeTopFeet = ridgeZ,
    isHip = sloped == 4, ridgeAboveEave = ridgeZ > z + 0.01
  };
});
